    }
}
```

What is the output of the following abstract class constructor invocation program?
```java
abstract class BaseEntity {
    String name;
    BaseEntity(String name) {
        this.name = name;
    }
    abstract void describe();
}
class ConcreteEntity extends BaseEntity {
    ConcreteEntity() {
        super("EntityOne");
    }
    @Override
    void describe() {
        System.out.print(name);
    }
}
public class Main {
    public static void main(String[] args) {
        BaseEntity be = new ConcreteEntity();
        be.describe();
    }
}
```

